// Fim dos Tempos · Arco 1 · Colinas Centrais · gerado por a1-encontros-colinas.js
const DADOS = {"enc":[{"k":"tolbert","nome":"Tolbert","tipo":"npc","roles":["tolbert"],"resumo":"Bardo de duas moedas sobre os olhos (por baixo, só buracos vazios). Cada moeda é uma alma, e ele tem várias outras numa bolsa. Desafia os personagens para um <b>duelo musical</b>: aposta uma alma, o personagem aposta a própria.","mec":"Três testes de Atuação opostos contra Tolbert (+15). Quem perde a alma a entrega como moeda: não pode ser ressuscitado e não vai a nenhum Reino dos Deuses. Quem ganha tem uma \"alma extra\" (pode vender a alma sem consequências). Enterrar a moeda ganha no Cemitério Errante dá +1 num atributo, como uma noite lá (acumula, mas não no mesmo atributo).","uso":"Testes dos Encontros → Duelo musical"},{"k":"abner","nome":"Abner","tipo":"npc","roles":["abner"],"resumo":"Adolescente qareen, pastor de Khalmyr totalmente fanático: quase tudo é \"uma bênção de Khalmyr\". Perturbado, mas inofensivo. Quer batizar os personagens sob Khalmyr.","mec":"Abençoa quem é gentil ou concorda com ele; amaldiçoa e ameaça os hostis. Efeito básico de <b>Bênção</b> (+1 em ataque e dano) ou <b>Perdição</b> (–1), até o fim da próxima cena.","uso":"Bênçãos e Maldições → Abner"},{"k":"quimby","nome":"Quimby Ulysses Arronax","tipo":"npc","roles":["quimby"],"resumo":"Anão vendedor de alquimia fajuta, numa carroça puxada por um gorloggh. Devoto de Hyninn: não engana além disso, mas solta \"nunca ouvi falar\" na conversa para achar outros devotos do Deus dos Ladrões.","mec":"Todo item alquímico custa <b>metade do preço</b>. Ao usar, 1d6: par funciona; ímpar funciona ao contrário (ácido, fogo e granada atingem o usuário, bálsamo causa dano, essência drena PM). Para um devoto de Hyninn revelado, ele avisa dos itens e indica um depósito a algumas horas com dois bálsamos e duas essências de verdade (pede que reponha).","uso":"Itens do Quimby + macro Alquimia do Quimby"},{"k":"gormaggor","nome":"Gormaggor","tipo":"parado","roles":["gormaggor"],"resumo":"Gigante que parece uma colina. A criatura mais antiga e poderosa das Centrais (a única maravilha original), velho demais e cansado: dorme quase sempre, já se fundiu às colinas e tem um braço preso. Deixou cair o cachimbo (feito de dois carvalhos) e não tem energia para pegá-lo.","mec":"Pôr o cachimbo na mão livre, enchê-lo (ele fuma quase qualquer planta) e acendê-lo conquista a amizade dele e uma fonte quase infinita (e tediosa) de informação: histórias do Herói Louco, o Diabo, o Cemitério. Lembra que \"há algum tempo\" o Herói Louco e o Rei Juiz passaram por ali. Com perspicácia: acordou quando a Tormenta começou a afetar as Colinas, e sente algo \"fazendo cócegas na terra\".","uso":"Tabela Histórias do Herói Louco"},{"k":"raguria","nome":"Raguria","tipo":"npc","roles":["raguria"],"resumo":"Bruxa caipira numa cabana afastada. Age como a \"bruxa má\" dos contos, mas não quer o mal dos personagens. Maligna, mas não perigosa se não for provocada. Conhece Cletus (não retribui a afeição dele) e sabe que \"algo ruim está se alastrando pelas Colinas\".","mec":"Gentileza: um prato especial do livro básico (uma porção para cada) ou o <b>Ensopado de Rabo de Lagarto e Olho de Sapo</b> (+1 na CD de magias arcanas). Rudeza: <b>Rogar Maldição</b> num deles (não pode se comunicar nem lançar magias, –5 em todos os testes, metade do deslocamento, até o dia seguinte ou o fim da próxima cena relevante), e sai levitando e gargalhando.","uso":"Bênçãos e Maldições → Raguria"},{"k":"arlo","nome":"Arlo \"Olho de Leite\"","tipo":"npc","roles":["arlo"],"resumo":"Caolho de olho leitoso, isolado, obcecado com sobrevivência. Acha que o Reinado vem tirar seus direitos e que \"algo sujo\" contamina as Centrais. Usa armas de pólvora. Dá informações do jeito mais paranoico possível e pode ajudar na caça ao Diabo.","mec":"Concurso de tiro: o personagem e Arlo fazem três testes de Pontaria (CD 15, 20 e 25). Mais sucessos vence (Arlo tem +10). Empate: a CD continua subindo +5.","uso":"Testes dos Encontros → Concurso de tiro"},{"k":"mungo","nome":"Mungo Joe","tipo":"npc","roles":["mungo"],"resumo":"Alambiqueiro caipira de chapelão, jardineira, sem camisa, descalço, desdentado e alegre. Vende uma dose da bebida fortíssima por T$ 1. Simpatia: a primeira é de graça e ele bebe junto.","mec":"Cada dose: Fortitude CD 15 (+1 por dose anterior no mesmo dia). Passou: +1 PM temporário. Falhou: enjoado por uma cena; na segunda falha, inconsciente por 1d12 horas.","uso":"Testes dos Encontros → Dose do Mungo Joe"},{"k":"puristas","nome":"Encontro de Puristas Caipiras","tipo":"npc","roles":["purista"],"resumo":"Odiadores de não humanos que mal conhecem a ideologia purista, mas abraçaram tudo. Um pastor prega a \"palavra de Valkaria\". Humanos vistos são convidados; não humanos, atacados.","mec":"Em combate, <b>8 recrutas puristas</b>. Não lutam até a morte: fogem se acharem que correm perigo (os não humanos têm \"vantagens injustas\"). Com eles, o panfleto (handout no diário).","uso":"Encontro do Dia → colocar tokens","qtd":8},{"k":"bode","nome":"O Homem-Bode","tipo":"npc","roles":["jonid"],"resumo":"Druida alucinado que vive transformado em bode, com os bodes. Só se distingue de um bode com profundo conhecimento de animais ou flagrando-o ao acordar (volta à forma humana dormindo). Abordado, foge ou luta.","mec":"Com extrema cautela e boas rolagens, conta que virou bode depois que a família morreu da \"doença misteriosa\" (mutações do Evento e corrupção da Tormenta). Nome: <b>Jonid</b>; família: Elmara, Savik e Diridda. Com sucesso extremo em testes sociais e boa interpretação, lança Curar Ferimentos (2d8+2) ou outra magia divina de 1º círculo.","uso":"Bênçãos e Maldições → Curar Ferimentos"},{"k":"duasPedras","nome":"A Cidade Fantasma de Duas Pedras","tipo":"local","roles":["aparicao"],"resumo":"Comunidade mineradora fechada pela Guilda dos Mineradores de Yuvalin há mais de 10 anos (tábuas no portão, placas oficiais). Quinquilharias, esqueletos de quem desafiou a Guilda e uma mina selada só com tiras de madeira. Fantasmas medrosos (Zadok, Draslo, Emeline, Aurinda) tentam afastar visitantes com armas fantasmagóricas; conversando, contam o que houve.","mec":"Procurando na aldeia: duas rolagens de dinheiro e uma de itens na Tabela 8–1 (sempre ND 1). Na mina, uma <b>aparição</b> e um veio de <b>metal arco-íris</b>. Minerar ali atrai a ira da Guilda (que pode se aliar à Irmandade no fim do arco).","uso":"Encontro do Dia → colocar tokens"},{"k":"ebenezer","nome":"Ebenezer","tipo":"npc","roles":["ebenezer"],"resumo":"Velho profeta herético de Thyatis. Oferece uma profecia para cada personagem, mas como aposta: se não se cumprir, Ebenezer errou e Thyatis lhe dá uma segunda chance; se se cumprir, o personagem terá de dar uma segunda chance a alguém. Ninguém é obrigado a aceitar.","mec":"O Mestre decide a profecia, que se resolve dentro da aventura. Não se cumpriu: o personagem ganha <b>+20 para gastar</b> em testes na próxima aventura (+5 num, +2 noutro...). Cumpriu: o Mestre pode <b>rolar de novo cinco testes</b> contra ele até o fim do arco.","uso":"Bênçãos e Maldições → Aposta de Ebenezer"},{"k":"museu","nome":"O Museu de Coisas Quase Vivas","tipo":"local","roles":["erneshia"],"resumo":"Museu de taxidermia de três andares. Dona Erneshia, acolhedora, cobra T$ 1 (qualquer simpatia vale entrada grátis). Misturas de bichos e criaturas do folclore: o coelho chifrudo, o meia-perna, o Ladrão de Rabos, um \"homem-bode\" recriado... e muitas recriações do Diabo das Colinas, cuja história ela conta com alegria.","mec":"Na caçada ao Diabo, Erneshia pode ir junto como <b>parceira ajudante mestre</b> (+4 em Atletismo, Percepção e Sobrevivência).","uso":"Perseguição ao Diabo → com Erneshia"},{"k":"diabo","nome":"O Diabo das Colinas","tipo":"npc","roles":["diabo"],"resumo":"Mito verdadeiro: criatura do tamanho de um anão, cabeça desproporcional, bocarra de dentes afiados, sempre sorrindo. O sétimo filho amaldiçoado ainda no ventre de um minerador avarento: nasceu não humano, matou a família e fugiu com o ouro. Aparece para viajantes e os convida a persegui-lo.","mec":"Quem o avista é perseguido para sempre: ele reaparece em todo <b>resultado par</b> desta tabela, além do resultado normal. Perseguição: o Diabo começa com 20 quadrados de vantagem e tem +17 em tudo; se abrir 50, some. Capturado, revela a riqueza e passa a ficar perto do covil com o pote de ouro (Tabela 8–1, dinheiro ND 7, ignorando 1 a 10).","uso":"Perseguição ao Diabo"},{"k":"sereias","nome":"Shanamarie, Shaylyne e Shadolenn","tipo":"parado","roles":["shanamarie","shaylyne","shadolenn"],"resumo":"Sereias do rio. Cantam para atrair aventureiros; quem se aproxima é roubado e, se resistir, afogado. Depois fogem nadando.","mec":"Quem vê ou ouve: Vontade oposta à Atuação delas (+10). Falha não é magia: o personagem fica inclinado a se aproximar e acha que são amigáveis (Intuição também é oposta pela Atuação). Na aproximação, uma distrai (Atuação), outra lança Hipnotismo ou Sono (CD 14) e a terceira rouba (Furtividade e Ladinagem +10). Então nadam para longe (natação 12m).","uso":"Testes dos Encontros → Canto e furto das sereias"},{"k":"cletus","nome":"Cletus Rigby","tipo":"npc","roles":["cletus"],"resumo":"Anão mago caipira, numa torre periclitante de cabanas sobre cabanas, entulhada como a casa de um acumulador. Odeia pessoas e é ranzinza; só conversa depois de ganhar confiança aos poucos. Quando o grupo chega, está transformado num <b>gato</b>: se ninguém mexer em nada, deixa-os em paz; se mexerem, vira anão e xinga (em casos extremos, ataca, e o grupo dificilmente vence). A casa fica sobre muito metal arco-íris.","mec":"Entrar exige Fortitude CD 15 (o cheiro): falha deixa enjoado. Um arcanista ou bardo que ganhe a confiança dele e <b>nunca o tenha ofendido</b> aprende uma magia arcana de 1º círculo. Sabe que a Tormenta se infiltra na terra, mas não vai fazer nada (os outros não perceberam? Idiotas!). Não sabe nada dos vilões.","uso":"Testes dos Encontros → Cabana / Ofensas"},{"k":"reston","nome":"Nada Mais que a Verdade Reston","tipo":"npc","roles":["reston"],"resumo":"Devota fundamentalista de Tanna-Toh compilando uma etnografia das Colinas. Pede que os heróis contem suas histórias e registra tudo. Não pode mentir e sofre até para omitir. Saiu de uma comunidade apocalíptica de fanáticos (hoje só esqueletos) com a desculpa da etnografia, e precisou fazê-la de verdade.","mec":"Testes de Inteligência (+4) contra CD 10, 15 ou 20 para saber qualquer coisa da região. Já ouviu boatos do Cemitério Errante (não acredita) e conhece histórias do Herói Louco. Tem o <b>pergaminho do Evento</b> (handout): não dá, mas deixa copiar. Família: Nunca Esconderei Nada de Meus Irmãos (pai), A Mentira Faz a Deusa Chorar (mãe), Toda a Verdade (irmã).","uso":"Testes dos Encontros → Nada Mais que a Verdade sabe?"},{"k":"ladrao","nome":"O Ladrão de Rabos","tipo":"npc","roles":["ladrao"],"resumo":"Mito verdadeiro: parece um cão sem pelos com vários rabos (de gambá, de cobra, de coiote...). Visto só de longe: fica mais distante, sem se mexer, quando alguém se aproxima. Só deixa ladrões chegarem perto (e, por eles, os colegas). Entidade que sussurra na mente e rouba rabos para dominar criaturas.","mec":"Um \"ladrão\" (a critério do Mestre) pode roubar um rabo: Ladinagem oposta à Percepção dele (+10). Roubado, ele implora e concede um <b>desejo</b> em troca: surge em até uma semana, distorcido de forma inofensiva (literal demais, ou primitivo/caipira). Na mesa original, roubou o rabo do minotauro Arius e o controlou em certos momentos.","uso":"Testes dos Encontros → Roubar um rabo"},{"k":"elmer","nome":"Elmer","tipo":"parado","roles":["elmer"],"resumo":"O dragão mendigo: peludo, comprido, asas de morcego e oito membros. Quer um tesouro, mas é preguiçoso e não é feroz. Pede moedas contando que é o único do seu tipo. Viciado em achbuld.","mec":"Com moedas e simpatia, fala da plantação de achbuld dos Gallobalt (e tenta arrancar mais). Generosidade demais: vira uma peste que segue o grupo. Fazê-lo sonhar com algo específico (Atuação, Diplomacia ou outra perícia) e tomar achbuld com ele leva o personagem ao sonho, de onde pode trazer um objeto: até duas melhorias, ou 1d10 × 100 Tibares. Nada mágico nem riquezas enormes.","uso":"Testes dos Encontros → Sonho de Elmer"},{"k":"fortunata","nome":"Fortunata","tipo":"npc","roles":["fortunata"],"resumo":"Jogadora e clériga de Nimb (talvez um avatar do Deus do Caos). Propõe Wyrt, mas aposta em qualquer coisa, sobretudo no resultado das aventuras. Prefere apostar segredos a dinheiro. Diz que Ebenezer \"não passa de um charlatão\" e aposta na caçada ao Diabo, se houver.","mec":"Jogatina +15. Na 1ª derrota, conta o segredo do tabuleiro. Na 2ª, conta do Cemitério Errante: quem ouve fica desorientado e \"perde\" algumas horas, e na próxima rolagem da tabela o grupo pode achar o Cemitério automaticamente. Depois disso, histórias do Herói Louco.","uso":"Testes dos Encontros → Aposta com Fortunata"},{"k":"cemiterio","nome":"O Cemitério Errante","tipo":"errante","roles":[],"resumo":"Local de luto pela divindade de Tilliann. Tumbas simples feitas por mortais e, no centro, uma tumba enorme de manufatura excepcional, com lápide lisa. Tristeza, melancolia e paz: uma saudade de algo que não se conhece. Pode surgir em qualquer lugar, várias vezes.","mec":"<b>10 unidades de metal arco-íris</b> no chão (arma leve 1, uma mão 2, duas mãos ou armadura leve 4, armadura pesada 8). Dormir ali: não recupera PM, mas +1 num atributo por uma semana; a segunda noite torna o bônus permanente. Quem é enterrado ali não vai aos Reinos dos Deuses; a energia passa à família. Um PJ enterrado não ressuscita, mas o próximo personagem do jogador ganha +1 num atributo.","uso":"Bênçãos e Maldições → Noite no Cemitério"}],"esp":[{"k":"ayla","nome":"Aylarianna Purpúrea (Ayla)","roles":["ayla"],"resumo":"A fada mais honesta de Arton: caixeira-viajante alquimista. Bálsamos e venenos funcionam; elixir de crescer cabelo e poção de sumir verruga, não. Escondida desde que um cliente insatisfeito a acusou (a culpada é a \"irmã gêmea\" que ela \"tem\").","mec":"Recruta revendedores para o <b>Empório Purpúrea</b> (funil invertido, não pirâmide!): kit de cosméticos de T$ 50 e T$ 10 por mês (pagos a Belinda, no Forte). O revendedor recruta NPCs (Diplomacia ou, francamente, Enganação), que compram dele o kit e pagam T$ 10 por mês até perceberem o golpe."},{"k":"ignis","nome":"Ignis Crae","roles":["ignis"],"resumo":"Golem de metal, paladino de Thyatis desde o nascimento, fundador da Ordem da Cavalaria da Redenção, que oferece recomeço a quem está no fundo do poço.","mec":"Parceiro <b>guardião veterano</b> (+3 na Defesa) enquanto achar que o grupo segue os preceitos de Thyatis. Num rumo sombrio (vício, roubo, corrupção), tenta recrutá-los para a Ordem: serve de penitência a devotos que quebraram suas Obrigações & Restrições."},{"k":"kiki","nome":"Kirzanaath \"Kiki\" Odello","roles":["kiki"],"resumo":"Medusa barda atrás de histórias, cerveja e fama. Esconde a raça até confiar. Teme virar monstruosa e quer saber o que houve com a mãe (obcecada por um tema que nem ela conhecia, fugiu com a filha e foi levada por desconhecidos). Cozinheira e boa em \"ler\" pessoas.","mec":"Parceira <b>ajudante veterana</b> (+2 em Atuação, Investigação e Ofício [cozinheiro]). Conta qualquer história do Herói Louco e prepara qualquer prato especial do livro básico sem custo. Fala da mãe e entra em negação."},{"k":"rexthor","nome":"Rexthor","roles":["rexthor"],"resumo":"O campeão das profundezas: dos Ermos Púrpuras, escravizado e posto nas arenas de Wynlla, libertado por uma aposta de uma mulher misteriosa ao sobreviver ao Abismo. Confia nas \"Deusas\" da Sorte, do Azar e do Caos (Nimb). Ingênuo, leal e bondoso por trás da fachada de exercícios, lutas e indecência.","mec":"Parceiro <b>fortão veterano</b>. Pode desafiar um combatente do grupo (sobretudo se houver magos) para um duelo \"amigável\": Defesa 18, 30 PV, +4 em resistências, Luta +10, 1d8+4 de impacto (a ficha dele já tem isso)."},{"k":"arius","nome":"Arius Gorgonius Dubitatius","roles":["arius"],"resumo":"Minotauro nobre de Tiberus, mago, filósofo e devoto de Tanna-Toh. Afastado pelo pai para uma legião longínqua, partiu atrás de conhecimento e só volta quando provar que a força não é o único poder. Dois metros, cabelos loiros trançados, postura encurvada, inseguro e empolgado com saber novo.","mec":"Dá qualquer informação ou pista à escolha do Mestre (Herói Louco, Templo do Vácuo, espaço de masmorra) e decifra idiomas desconhecidos, como a língua dos gnomos."},{"k":"cacadores","nome":"Chèvre e Timm","roles":["chevre","timm"],"resumo":"Caçadores de recompensas. Chèvre: sátiro malandro, envenenador, infiltrador e ladrão, com uma flauta-zarabatana de dardos envenenados. Timm: mago humano pomposo e enigmático, obcecado por fogo, que some numa explosão de chamas e fumaça. Põem o contrato acima de tudo.","mec":"Chèvre é parceiro <b>perseguidor veterano</b>; Timm, <b>destruidor (fogo) veterano</b>. No fim de qualquer interação, 50% de chance de trair o grupo (levam algo que o grupo precisa ou um NPC): disputa de Iniciativa do grupo contra a dupla (+10)."}]};
(async function macroEncontro(D) {
		const ESTADO = "fdtColinas";
		const TAG = "a1colinas";
		const est = foundry.utils.deepClone(game.user.getFlag("world", ESTADO) ?? {});
		est.dia ??= 0;
		est.vistos ??= {};
		est.descobertos ??= [];
		est.caes ??= true;
		const op = D.enc.map((e, i) => `<option value="${i + 1}">${i + 1}. ${e.nome}${est.descobertos.includes(e.k) ? " (descoberto)" : est.vistos[e.k] ? ` (visto ${est.vistos[e.k]}x)` : ""}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Colinas Centrais · Encontro do Dia" },
			position: { width: 480 },
			content: `
				<p>Dia ${est.dia} nas Colinas. ${est.diabo ? "<b>O Diabo das Colinas já foi avistado</b> (aparece em todo resultado par). " : ""}${est.cemiterio ? "<b>Fortunata contou do Cemitério:</b> a próxima rolagem o encontra. " : ""}</p>
				<div class="form-group"><label>Ação</label><select name="acao">
					<option value="rolar">Rolar o encontro do dia (1d20)</option>
					<option value="escolher">Usar um resultado escolhido</option>
					<option value="especial">Rolar só um encontro especial (1d6)</option>
					<option value="estado">Ver o que já foi encontrado</option>
					<option value="zerar">Zerar (começar as Colinas de novo)</option></select></div>
				<div class="form-group"><label>Resultado escolhido</label><select name="numero">${op}</select></div>
				<div class="form-group"><label>Resultado inviável rola os Cães das Colinas (1d6)</label><input type="checkbox" name="caes" ${est.caes ? "checked" : ""}></div>
				<div class="form-group"><label>Colocar os tokens (ocultos) perto do 1º token selecionado</label><input type="checkbox" name="tokens"></div>`,
			ok: { label: "Aplicar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const whisper = ChatMessage.getWhisperRecipients("GM");
		if (res.acao === "zerar") {
			await game.user.unsetFlag("world", ESTADO);
			return ui.notifications.info("Encontros das Colinas zerados.");
		}
		if (res.acao === "estado") {
			const vistos = Object.entries(est.vistos).map(([k, n]) => `${(D.enc.find((e) => e.k === k) ?? D.esp.find((e) => e.k === k))?.nome ?? k} (${n}x)`);
			return ChatMessage.create({ whisper, content: `<h3>Colinas Centrais · ${est.dia} dia(s)</h3>
				<p><b>Encontrados:</b> ${vistos.join(", ") || "ninguém ainda"}.</p>
				<p><b>Locais e NPCs fixos descobertos (cole os adesivos):</b> ${est.descobertos.map((k) => D.enc.find((e) => e.k === k)?.nome).join(", ") || "nenhum"}.</p>
				<p>Diabo das Colinas: ${est.diabo ? (est.diaboCapturado ? "capturado (fica perto do covil com o pote de ouro)" : "avistado, persegue o grupo") : "ainda não avistado"}.${est.cemiterio ? " O próximo encontro é o Cemitério Errante." : ""}</p>
				${est.log?.length ? `<p style="font-size:0.85em">${est.log.slice(-10).join(" · ")}</p>` : ""}` });
		}
		est.caes = !!res.caes;
		const rolls = [];
		const roles = (lista) => lista.map((r) => game.actors.find((a) => a.getFlag("world", "fdt") === TAG && a.getFlag("world", "fdtRole") === r)).filter(Boolean);
		const diario = game.journal.find((j) => j.getFlag("world", "fdt") === TAG && j.getFlag("world", "fdtRole") === "diarioColinas");
		const linkPg = (nome) => {
			const pg = diario?.pages.find((x) => x.name === nome);
			return pg ? `@UUID[${pg.uuid}]{página no diário}` : "";
		};
		const bloco = (e, titulo) => {
			const as = roles(e.roles ?? []);
			return `<h3>${titulo}</h3><p>${e.resumo}</p><p><b>Mecânica:</b> ${e.mec}</p>
				<p style="font-size:0.85em">${as.map((a) => `@UUID[${a.uuid}]{${a.name}}`).join(", ")}${as.length ? " · " : ""}${linkPg(e.nome)}${e.uso ? ` · <i>${e.uso}</i>` : ""}</p>`;
		};
		const especial = async () => {
			const r = await new Roll("1d6").evaluate();
			rolls.push(r);
			const e = D.esp[r.total - 1];
			est.vistos[e.k] = (est.vistos[e.k] ?? 0) + 1;
			return { e, html: bloco(e, `Encontro especial (1d6 = ${r.total}): ${e.nome}`) };
		};
		let html = "";
		const aparecem = [];
		if (res.acao === "especial") {
			const x = await especial();
			html = x.html;
			aparecem.push(x.e);
		} else {
			est.dia++;
			let n;
			if (res.acao === "escolher") n = Number(res.numero);
			else if (est.cemiterio) {
				n = 20;
				est.cemiterio = false;
				html += "<p><i>Quem ouviu Fortunata se desorienta e \"perde\" algumas horas... e, de repente, o grupo está diante do Cemitério Errante.</i></p>";
			} else {
				const r = await new Roll("1d20").evaluate();
				rolls.push(r);
				n = r.total;
			}
			const e = D.enc[n - 1];
			const fixo = e.tipo === "local" || e.tipo === "parado";
			const inviavel = fixo && est.descobertos.includes(e.k);
			html = `<p><b>Dia ${est.dia} nas Colinas Centrais · 1d20 = ${n}</b></p>${html}`;
			if (inviavel) {
				html += `<p><b>${e.nome}</b> já foi descoberto: resultado inviável.</p>`;
				if (est.caes) {
					const x = await especial();
					html += x.html;
					aparecem.push(x.e);
				} else html += "<p>O grupo passa por lá de novo, ou o dia segue sem novidades.</p>";
			} else {
				html += bloco(e, e.nome);
				aparecem.push(e);
				est.vistos[e.k] = (est.vistos[e.k] ?? 0) + 1;
				if (fixo) est.descobertos.push(e.k);
				if (e.tipo === "local" || e.tipo === "parado") html += "<p style=\"font-size:0.85em\">Fixo: marque no mapa (adesivo). Rolar de novo vira resultado inviável.</p>";
			}
			if (e.k === "diabo" && !est.diabo) {
				est.diabo = true;
				html += "<p><b>O Diabo foi avistado:</b> a partir de agora ele reaparece em todo resultado par desta tabela.</p>";
			} else if (est.diabo && !est.diaboCapturado && n % 2 === 0 && e.k !== "diabo") {
				const d = D.enc.find((x) => x.k === "diabo");
				html += `<hr><p><b>Resultado par:</b> o Diabo das Colinas aparece de novo, sorrindo, convidando a ser perseguido.</p><p style="font-size:0.85em">${roles(d.roles).map((a) => `@UUID[${a.uuid}]{${a.name}}`).join("")} · <i>${d.uso}</i></p>`;
				aparecem.push(d);
			}
			est.log = [...(est.log ?? []), `D${est.dia}: ${aparecem.map((x) => x.nome).join(" + ") || `${e.nome} (repetido)`}`].slice(-30);
		}
		if (res.tokens) {
			const ref = canvas.tokens.controlled[0];
			const gs = canvas.grid.size;
			const cx = ref ? ref.document.x : canvas.stage.pivot.x - gs / 2;
			const cy = ref ? ref.document.y : canvas.stage.pivot.y - gs / 2;
			const docs = [];
			let i = 0;
			for (const e of aparecem) for (const a of roles(e.roles ?? [])) {
				for (let q = 0; q < (e.qtd ?? 1); q++, i++) {
					const ang = (i / 8) * 2 * Math.PI;
					const raio = 4 + Math.floor(i / 8) * 2;
					docs.push((await a.getTokenDocument({ x: cx + Math.round(Math.cos(ang) * raio) * gs, y: cy + Math.round(Math.sin(ang) * raio) * gs, hidden: true })).toObject());
				}
			}
			if (docs.length) {
				await canvas.scene.createEmbeddedDocuments("Token", docs);
				html += `<p style="font-size:0.85em">${docs.length} token(s) colocados <b>ocultos</b> em volta ${ref ? `de ${ref.name}` : "do centro da tela"}.</p>`;
			}
		}
		await game.user.setFlag("world", ESTADO, est);
		ChatMessage.create({ content: html, rolls, whisper });
	})(DADOS);
